from __future__ import annotations

import json
import logging
import time
from pathlib import Path

from .models import Signal

logger = logging.getLogger(__name__)


class SignalState:
    def __init__(self, path: str) -> None:
        self.path = Path(path)
        self.last_sent: dict[str, float] = {}
        if self.path.exists():
            try:
                data = json.loads(self.path.read_text(encoding="utf-8"))
                self.last_sent = {
                    str(key): float(value)
                    for key, value in data.get("last_sent", {}).items()
                }
            except (OSError, ValueError, TypeError, json.JSONDecodeError):
                self.last_sent = {}

    def on_cooldown(self, signal: Signal, cooldown_minutes: int) -> bool:
        previous = self.last_sent.get(signal.cooldown_key)
        return previous is not None and time.time() - previous < cooldown_minutes * 60

    def mark_sent(self, signal: Signal) -> None:
        self.last_sent[signal.cooldown_key] = time.time()
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            temporary = self.path.with_suffix(self.path.suffix + ".tmp")
            temporary.write_text(
                json.dumps({"last_sent": self.last_sent}, indent=2), encoding="utf-8"
            )
            temporary.replace(self.path)
        except OSError as exc:
            logger.warning(
                "Could not persist cooldown state to %s: %s (cooldowns will reset on restart)",
                self.path,
                exc,
            )

from __future__ import annotations

import requests


class TelegramAPIError(RuntimeError):
    pass


def _call(
    token: str, method: str, params: dict | None = None, timeout: int = 20
) -> object:
    url = f"https://api.telegram.org/bot{token}/{method}"
    try:
        response = requests.get(url, params=params, timeout=timeout)
    except requests.RequestException as exc:
        raise TelegramAPIError(f"Could not reach Telegram: {exc}") from exc
    try:
        payload = response.json()
    except ValueError as exc:
        raise TelegramAPIError("Telegram returned a non-JSON response.") from exc
    if not payload.get("ok"):
        description = payload.get("description", "unknown error")
        if response.status_code == 409:
            raise TelegramAPIError(
                "Another process is polling this bot. Stop bot.py --loop, then retry."
            )
        raise TelegramAPIError(f"Telegram rejected the request: {description}")
    return payload.get("result")


def get_me(token: str, timeout: int = 20) -> dict:
    result = _call(token, "getMe", timeout=timeout)
    return result if isinstance(result, dict) else {}


def get_updates(token: str, timeout: int = 20) -> list[dict]:
    result = _call(
        token, "getUpdates", {"timeout": 0, "limit": 100}, timeout=timeout
    )
    return result if isinstance(result, list) else []


def chat_from_update(update: dict) -> dict | None:
    for key in ("message", "edited_message", "channel_post", "edited_channel_post"):
        payload = update.get(key)
        if isinstance(payload, dict) and isinstance(payload.get("chat"), dict):
            return payload["chat"]
    member = update.get("my_chat_member")
    if isinstance(member, dict) and isinstance(member.get("chat"), dict):
        return member["chat"]
    return None


def collect_chats(updates: list[dict]) -> dict[int, dict]:
    chats: dict[int, dict] = {}
    for update in updates:
        chat = chat_from_update(update)
        if chat and "id" in chat:
            chats[int(chat["id"])] = chat
    return chats

import unittest
from unittest.mock import patch

from scalping_bot.telegram_api import (
    TelegramAPIError,
    chat_from_update,
    collect_chats,
    get_me,
    get_updates,
)


class FakeResponse:
    def __init__(self, status_code=200, payload=None) -> None:
        self.status_code = status_code
        self._payload = payload if payload is not None else {"ok": True}

    def json(self):
        if isinstance(self._payload, Exception):
            raise self._payload
        return self._payload


class TelegramAPITests(unittest.TestCase):
    def test_get_me_returns_bot(self) -> None:
        payload = {"ok": True, "result": {"username": "my_bot"}}
        with patch("scalping_bot.telegram_api.requests.get") as get:
            get.return_value = FakeResponse(payload=payload)
            self.assertEqual(get_me("token"), {"username": "my_bot"})

    def test_get_updates_returns_list(self) -> None:
        payload = {"ok": True, "result": [{"update_id": 1}]}
        with patch("scalping_bot.telegram_api.requests.get") as get:
            get.return_value = FakeResponse(payload=payload)
            self.assertEqual(get_updates("token"), [{"update_id": 1}])

    def test_conflict_has_actionable_message(self) -> None:
        payload = {"ok": False, "description": "Conflict"}
        with patch("scalping_bot.telegram_api.requests.get") as get:
            get.return_value = FakeResponse(409, payload)
            with self.assertRaises(TelegramAPIError) as caught:
                get_updates("token")
        self.assertIn("bot.py --loop", str(caught.exception))

    def test_non_json_response_is_rejected(self) -> None:
        with patch("scalping_bot.telegram_api.requests.get") as get:
            get.return_value = FakeResponse(payload=ValueError("bad"))
            with self.assertRaises(TelegramAPIError):
                get_me("token")

    def test_collect_chats_handles_private_group_and_channel(self) -> None:
        updates = [
            {"message": {"chat": {"id": 1, "type": "private"}}},
            {"my_chat_member": {"chat": {"id": -2, "type": "group"}}},
            {"channel_post": {"chat": {"id": -3, "type": "channel"}}},
            {"edited_message": {"chat": {"id": 1, "type": "private"}}},
            {"message": {}},
        ]
        chats = collect_chats(updates)
        self.assertEqual(set(chats), {1, -2, -3})

    def test_chat_from_update_returns_none_for_unknown(self) -> None:
        self.assertIsNone(chat_from_update({"update_id": 9}))


if __name__ == "__main__":
    unittest.main()

